from h import *
R=[]
R.append((6630821,{
"es":L("Arroz con leche (flan de arroz)",
"Si usted es latino, ¡seguramente ha probado este delicioso postre! Lo que probablemente no ha probado es una versión apta para personas con diabetes que le encantará tanto como el platillo tradicional. Esta versión sin culpa es libre de azúcar y aporta fibra adicional del arroz integral y las semillas de linaza.",
"4","3/4 taza",
["1 taza de arroz integral instantáneo sin cocinar","2 tazas de leche sin grasa","1 taza de agua","2 cucharadas de endulzante granulado sin calorías","1 tira entera de cáscara de naranja (de 3 pulgadas)","1 rama de canela entera","1 cucharada de semillas de linaza enteras","3 clavos de olor enteros","1 cucharadita de extracto de vainilla","1/2 cucharadita de canela molida"],
["Prepare el arroz según las instrucciones del paquete.",
"Combine el arroz cocido, la leche, el agua, el sustituto de azúcar, la cáscara de naranja, la rama de canela, las semillas de linaza y los clavos de olor en una cacerola mediana; deje que hierva. Reduzca el fuego a medio-bajo y cocine a fuego lento, revolviendo con frecuencia, hasta que el arroz con leche esté espeso y cremoso, aproximadamente 20 minutos.",
"Retire del fuego. Saque y deseche la cáscara de naranja, la rama de canela y los clavos de olor. Incorpore la vainilla y la canela molida."]),
"ar":L("أرز بالحليب (كاسترد الأرز)",
"إذا كنت من أمريكا اللاتينية، فمن المؤكد أنك تناولت هذه الحلوى اللذيذة! لكن ما لم تتناوله على الأرجح هو نسخة مناسبة لمرضى السكري ستعجبك بقدر الطبق التقليدي. هذه النسخة الخالية من الشعور بالذنب خالية من السكر وتتميز بألياف إضافية من الأرز البني وبذور الكتان.",
"4","¾ كوب",
["1 كوب أرز بني سريع التحضير غير مطبوخ","2 كوب حليب خالٍ من الدسم","1 كوب ماء","2 ملعقة كبيرة محلٍّ حبيبي خالٍ من السعرات","1 شريحة كاملة من قشر البرتقال (3 بوصات)","1 عود قرفة كامل","1 ملعقة كبيرة بذور الكتان كاملة","3 حبات قرنفل (كاملة)","1 ملعقة صغيرة خلاصة الفانيليا","½ ملعقة صغيرة قرفة مطحونة"],
["حضّر الأرز وفق تعليمات العبوة.",
"اخلط الأرز المطبوخ والحليب والماء وبديل السكر وقشر البرتقال وعود القرفة وبذور الكتان والقرنفل في قدر متوسط؛ واتركه حتى يغلي. خفّض النار إلى متوسطة إلى هادئة ودعه يغلي بهدوء مع التحريك المتكرر حتى يثخن الأرز بالحليب ويصبح كريميًا، لمدة 20 دقيقة تقريبًا.",
"ارفعه عن النار. أخرج قشر البرتقال وعود القرفة والقرنفل وتخلص منها. أضف الفانيليا والقرفة المطحونة وقلّب."])}))
R.append((6631366,{
"es":L("Batido de naranja cremosa (creamsicle)",
"Si le encantan las paletas heladas de naranja cremosa, ¡le encantará este batido! Diseñada para ser apta para personas con diabetes, esta receta usa yogur griego rico en proteína para lograr un batido satisfactorio.",
"2","8 oz",
["1 naranja mediana (pelada y en gajos)","1/2 plátano mediano (congelado)","1/2 taza de jugo de naranja","1/2 taza de yogur griego natural sin grasa","1/2 cucharadita de extracto de vainilla"],
["Coloque la naranja, el plátano, el jugo de naranja, el yogur y la vainilla en una licuadora. Licúe hasta obtener una mezcla suave.",
"Sirva en dos vasos. Disfrútelo de inmediato."]),
"ar":L("سموذي البرتقال الكريمي",
"إذا كنت تحب مثلجات البرتقال الكريمية، فستحب هذا السموذي! صُممت هذه الوصفة لتكون مناسبة لمرضى السكري، وتستخدم الزبادي اليوناني الغني بالبروتين لتحضير سموذي مشبع.",
"2","8 أونصات",
["1 حبة برتقال متوسطة (مقشرة ومفصصة)","½ حبة موز متوسطة (مجمدة)","½ كوب عصير برتقال","½ كوب زبادي يوناني سادة خالٍ من الدسم","½ ملعقة صغيرة خلاصة الفانيليا"],
["ضع البرتقال والموز وعصير البرتقال والزبادي والفانيليا في الخلاط. اخلطها حتى يصبح الخليط ناعمًا.",
"اسكبه في كوبين. استمتع به فورًا."])}))
R.append((6631489,{
"es":L("Avena cocida","Información nutricional de la avena","1","1 taza, cocida",["1 taza de avena (cocida)"],[]),
"ar":L("دقيق الشوفان المطبوخ","المعلومات الغذائية لدقيق الشوفان","1","1 كوب، مطبوخ",["1 كوب دقيق شوفان (مطبوخ)"],[])}))
R.append((6631528,{
"ar":L("شرائح السمك المخبوزة مع طبقة الزعتر وخردل ديجون",
"قدّم شرائح السمك المخبوزة اللذيذة هذه مع البطاطا الحلوة المشوية وكرنب بروكسل. إنه طبق أنيق ومناسب لمرضى السكري يمكنك تحضيره لحبيبك في مناسبة خاصة!",
"4","3 أونصات سمك + 1 ملعقة كبيرة طبقة",
["1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","4 شرائح (4 أونصات) من سمك الهامور أو أي سمك آخر معتدل النكهة (مغسولة ومجففة)","3 ملاعق كبيرة سمن نباتي (مارجرين) خفيف في علبة (خالٍ من الدهون المتحولة)","2 ملعقة كبيرة بقدونس طازج (مفروم ناعمًا)","1 ملعقة صغيرة خردل ديجون (الأقل صوديومًا المتاح)","¼ ملعقة صغيرة زعتر مجفف (مفتت)","¼ ملعقة صغيرة صلصة الفلفل الحار الأحمر","⅛ ملعقة صغيرة ملح"],
["سخّن الفرن مسبقًا إلى 350° فهرنهايت (175° مئوية). رش صينية خبز برفق ببخاخ الطهي.",
"ضع السمك على صينية الخبز. اخبزه لمدة 18-20 دقيقة، أو حتى يتفتت السمك بسهولة عند اختباره بالشوكة.",
"في الأثناء، في وعاء صغير، اخلط بقية المكونات.",
"ادهن خليط السمن النباتي (المارجرين) على السمك."])}))
R.append((6631665,{
"ar":L("طبق الخضار للمناسبات مع الحمص – وصفة سريعة",
"من المدهش أن الناس يتناولون المزيد من الخضار عندما تكون أمامهم، ومعروضة بشكل جيد ومقدَّمة مع غمس لذيذ. الحمص غمس صحي مصنوع من الحمص الحب ويتوفر بنكهات متنوعة.",
"10","1 كوب خضار + 2 ملعقة كبيرة حمص",
["1¼ كوب حمص بالفلفل الأحمر (جاهز معبأ)","1 باينت طماطم عنبية","3 كوب بازلاء سكر","3 كوب زهيرات بروكلي","1 حبة خيار متوسطة (مقشرة ومقطعة شرائح)","2 حبة فلفل رومي أحمر متوسطة (مقطعة شرائح)"],
["رتّب الخضار على طبق تقديم كبير ودائري. ضع الخضار الحمراء بالتناوب مع الخضار الخضراء على شكل دائرة على الطبق.",
"ضع الحمص في وعاء صغير في وسط الطبق."])}))
R.append((6632676,{
"es":L("Pasta e fagioli (sopa de pasta y frijoles)",
"Esta abundante sopa italiana es un excelente almuerzo o acompañamiento para su comida navideña. Para reducir el tiempo de preparación, pique rápidamente la cebolla, el ajo, el apio y las zanahorias con un procesador de alimentos.",
"6","1 taza",
["1 rocío, 0.25 g de aceite en aerosol antiadherente","4 rebanadas de tocino de pavo (picado)","1 cebolla mediana (finamente picada)","2 dientes de ajo (picados)","2 tallos de apio (picados en cubos pequeños)","2 zanahorias medianas (picadas en cubos pequeños)","3 1/2 tazas de caldo de pollo bajo en sodio (sin grasa)","2 latas (16 oz) de frijoles cannellini (enjuagados y escurridos)","1 lata (15 oz) de tomates picados enlatados (sin sal añadida, escurridos)","1 cucharadita de perejil (seco)","1 cucharadita de albahaca (seca)","1/4 cucharadita de pimienta negra","1 taza de pasta de quinoa en forma de conchitas pequeñas (sin cocinar)","1/4 taza de queso parmesano (recién rallado)"],
["Cubra una olla grande para sopa con aceite en aerosol a fuego alto. Agregue el tocino y saltee hasta que esté crujiente.",
"Reduzca el fuego a medio y agregue la cebolla, el ajo, el apio y las zanahorias. Saltee aproximadamente de 5 a 7 minutos o hasta que las verduras empiecen a dorarse. Agregue el caldo y cocine a fuego lento durante 5 minutos.",
"Incorpore los frijoles, los tomates, el perejil, la albahaca y la pimienta y cocine a fuego lento durante 10 minutos. Agregue la pasta y continúe cocinando a fuego lento de 10 a 15 minutos o hasta que la pasta esté al dente.",
"Sirva la sopa en un tazón espolvoreada con queso parmesano."]),
"ar":L("معكرونة وفاصولياء (باستا فاجيولي)",
"هذه الشوربة الإيطالية المشبعة غداء رائع أو طبق جانبي مع وجبة العيد. لتقليل وقت التحضير، قطّع البصل والثوم والكرفس والجزر بسرعة باستخدام محضّر الطعام.",
"6","1 كوب",
["1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","4 شرائح لحم ديك رومي مقدد (مقطعة)","1 حبة بصل متوسطة (مفرومة ناعمًا)","2 فص ثوم (مفروم)","2 ساق كرفس (مقطعة مكعبات صغيرة)","2 حبة جزر متوسطة (مقطعة مكعبات صغيرة)","3½ كوب مرق دجاج قليل الصوديوم (خالٍ من الدسم)","2 علبة (16 أونصة) فاصولياء كانيليني (مشطوفة ومصفّاة)","1 علبة (15 أونصة) طماطم معلبة مقطعة مكعبات (بدون ملح مضاف، مصفّاة)","1 ملعقة صغيرة بقدونس (مجفف)","1 ملعقة صغيرة ريحان (مجفف)","¼ ملعقة صغيرة فلفل أسود","1 كوب معكرونة كينوا على شكل أصداف صغيرة (غير مطبوخة)","¼ كوب جبن بارميزان (مبشور طازجًا)"],
["غطِّ قدر حساء كبيرًا ببخاخ الطهي على نار عالية. أضف لحم الديك الرومي المقدد وقلّبه حتى يصبح مقرمشًا.",
"خفّض النار إلى متوسطة وأضف البصل والثوم والكرفس والجزر. قلّبها لمدة 5-7 دقائق تقريبًا أو حتى تبدأ الخضار في التحمير. أضف المرق ودعه يغلي بهدوء لمدة 5 دقائق.",
"أضف الفاصولياء والطماطم والبقدونس والريحان والفلفل وقلّب ودعه يغلي بهدوء لمدة 10 دقائق. أضف المعكرونة واستمر في الغليان الهادئ لمدة 10-15 دقيقة أو حتى تنضج المعكرونة وتبقى متماسكة قليلًا (آل دنتي).",
"قدّم الشوربة في وعاء مرشوشة بجبن البارميزان."])}))
R.append((6632910,{
"es":L("Brochetas de camarón con limón y ajo",
"Estas brochetas de camarón con limón y ajo son versátiles y se pueden servir junto a una ensalada, sobre arroz integral o con sus verduras favoritas. La combinación de limón y ajo aporta un toque vivo y sabroso a los camarones a la parrilla.",
"4","2 brochetas",
["8 brochetas de bambú enteras","2 limones medianos","2 cucharadas de aceite de oliva","3 dientes de ajo (picados)","1 cucharadita de orégano seco","1 cucharada de romero fresco (picado)","1/4 cucharadita de pimienta negra","1 libra de camarones (grandes, pelados y desvenados)"],
["Si usa brochetas de madera, remójelas en agua por al menos 15 minutos para evitar que se quemen al asar.",
"Ralle la cáscara y exprima el jugo de uno de los limones. Corte el otro en rodajas finas.",
"En un tazón, combine el aceite de oliva, el ajo picado, la ralladura de limón, el jugo de limón, el orégano seco, el romero y la pimienta negra.",
"Agregue los camarones pelados y desvenados al adobo, asegurándose de que queden bien cubiertos. Déjelos marinar por al menos 15 minutos",
"Precaliente la parrilla o sartén para asar a fuego medio-alto.",
"Ensarte los camarones marinados en las brochetas, junto con una o dos rodajas de limón por brocheta.",
"Coloque las brochetas de camarón en la parrilla precalentada y cocine aproximadamente de 2 a 3 minutos por lado o hasta que los camarones estén completamente cocidos y se chamusquen ligeramente."]),
"ar":L("أسياخ الجمبري بالليمون والثوم",
"أسياخ الجمبري بالليمون والثوم هذه متعددة الاستخدامات ويمكن تقديمها بجانب السلطة أو فوق الأرز البني أو مع خضارك المفضلة. يضيف مزيج الليمون والثوم نكهة منعشة ولذيذة إلى الجمبري المشوي.",
"4","سيخان",
["8 أسياخ خيزران كاملة","2 حبة ليمون متوسطة","2 ملعقة كبيرة زيت زيتون","3 فصوص ثوم (مفروم)","1 ملعقة صغيرة أوريجانو مجفف","1 ملعقة كبيرة إكليل الجبل (روزماري) طازج (مفروم)","¼ ملعقة صغيرة فلفل أسود","1 رطل جمبري (كبير، مقشر ومنزوع الخيط)"],
["إذا كنت تستخدم أسياخًا خشبية، فانقعها في الماء لمدة 15 دقيقة على الأقل لمنعها من الاحتراق أثناء الشواء.",
"اطحن قشر إحدى حبتي الليمون وعصرها. وقطّع الأخرى إلى شرائح رفيعة.",
"في وعاء، اخلط زيت الزيتون والثوم المفروم وقشر الليمون المبشور وعصير الليمون والأوريجانو المجفف وإكليل الجبل والفلفل الأسود.",
"أضف الجمبري المقشر ومنزوع الخيط إلى التتبيلة، مع التأكد من تغطيته جيدًا. اتركه ينقع في التتبيلة لمدة 15 دقيقة على الأقل",
"سخّن الشواية أو مقلاة الشواء مسبقًا على حرارة متوسطة إلى عالية.",
"اغرز الجمبري المتبّل في الأسياخ، مع شريحة ليمون أو شريحتين لكل سيخ.",
"ضع أسياخ الجمبري على الشواية المسخّنة واشوِها لمدة 2–3 دقائق تقريبًا لكل جانب أو حتى ينضج الجمبري تمامًا ويتفحّم قليلًا."])}))
R.append((6633224,{
"ar":L("إيج فو يونغ بالخضار",
"جرّب هذه الوجبة لطبق فريد مستوحى من المطبخ الآسيوي وسهل على الميزانية أيضًا. إنه رائع للإفطار أو الغداء أو العشاء!",
"4","1 قرص",
["2 بخّة، 0.50 غرام بخاخ طهي غير لاصق (يُقسَّم)","1 ملعقة صغيرة زيت الكانولا","8 حبات فطر أبيض (أزرار) متوسطة (مقطعة)","1 حبة كوسا صغيرة (مبشورة)","½ حبة بصل صغيرة (مفرومة ناعمًا)","1 كوب براعم الفاصولياء المعلبة (مصفّاة ومشطوفة)","4 أونصات سائلة بديل البيض","1 بيضة كبيرة","3 ملاعق كبيرة دقيق متعدد الاستخدامات","½ ملعقة صغيرة ملح (اختياري)","1 ملعقة كبيرة نشا الذرة","1 ملعقة صغيرة بديل سكر قليل السعرات","2 ملعقة صغيرة صلصة الصويا قليلة الصوديوم","1½ كوب مرق دجاج قليل الصوديوم (خالٍ من الدسم)"],
["ضع بخاخ الطهي وزيت الكانولا في مقلاة غير لاصقة على نار متوسطة. أضف الفطر والكوسا والبصل. قلّبها حتى يجف الفطر ويصبح البصل شفافًا، لمدة 5-7 دقائق تقريبًا. أضف براعم الفاصولياء وقلّب 2-3 دقائق إضافية. ضعه جانبًا ليبرد.",
"في وعاء متوسط، اخفق بديل البيض والبيضة معًا. أضف الدقيق مع الخفق ثم أضف خليط الخضار والملح (اختياري) وقلّب. اخلط جيدًا.",
"على نار متوسطة إلى عالية، أعد رش المقلاة غير اللاصقة ببخاخ الطهي واسكب الخليط بمقدار ½ كوب مغروف لتشكيل أقراص. اطهِ جيدًا على الجانبين حتى يصبح لونها ذهبيًا، لمدة 4-5 دقائق لكل جانب. أخرج الأقراص من المقلاة وضعها جانبًا.",
"في وعاء صغير، اخلط نشا الذرة والمحلّي قليل أو منعدم السعرات وصلصة الصويا ومرق الدجاج. اخلط جيدًا. أضف هذا الخليط إلى المقلاة الساخنة واتركه حتى يغلي؛ ثم خفّض النار ودعه يغلي بهدوء 5 دقائق لتحضير الصلصة.",
"اسكب الصلصة فوق الأقراص وقدّمها ساخنة."])}))
R.append((6633572,{
"es":L("Salmón y espárragos con hierbas en bandeja",
"Las comidas en una sola bandeja son rápidas, fáciles y no dejan mucho que limpiar. ¿Qué podría ser mejor? Esta versión de salmón y espárragos es apta para personas con diabetes y está repleta de ácidos grasos omega-3, lo que la convierte en una opción saludable para una comida entre semana.",
"4","1 filete + 1/4 de los espárragos",
["2 cucharadas de aceite de oliva","1 cucharada de eneldo fresco (picado)","2 cucharaditas de ralladura de limón (de 1 limón mediano)","1/2 cucharadita de sal kosher","1/8 cucharadita de pimienta negra (al gusto)","4 filetes (de 5 onzas) de salmón rojo (sockeye)","1 manojo de espárragos (cortados en puntas largas)","2 cucharadas de jugo de limón"],
["Caliente el horno a 375°F y cubra una bandeja para hornear con papel pergamino.",
"En un tazón pequeño, combine el aceite de oliva, el eneldo picado, la ralladura de limón, el jugo de limón, la sal kosher y la pimienta.",
"Coloque los filetes de salmón y los espárragos en una bandeja para hornear y ponga con una cuchara la mezcla de hierbas sobre cada filete.",
"Hornee hasta que el salmón alcance una temperatura interna de 145°F, aproximadamente 20 minutos, y los espárragos estén tiernos."]),
"ar":L("سلمون وهليون بالأعشاب على صينية واحدة",
"وجبات الصينية الواحدة سريعة وسهلة ولا تتطلب الكثير من التنظيف. ما الذي يمكن أن يكون أفضل من ذلك؟ هذه النسخة من السلمون والهليون مناسبة لمرضى السكري وغنية بالأحماض الدهنية أوميغا-3، مما يجعلها خيارًا صحيًا لوجبة أيام الأسبوع.",
"4","1 شريحة + ¼ من أعواد الهليون",
["2 ملعقة كبيرة زيت زيتون","1 ملعقة كبيرة شبت طازج (مفروم)","2 ملعقة صغيرة قشر ليمون مبشور (من حبة ليمون متوسطة)","½ ملعقة صغيرة ملح كوشر","⅛ ملعقة صغيرة فلفل أسود (حسب الذوق)","4 شرائح (5 أونصات) سلمون سوكاي","1 حزمة هليون (مقطوعة إلى أعواد طويلة)","2 ملعقة كبيرة عصير ليمون"],
["سخّن الفرن إلى 375° فهرنهايت (190° مئوية) وغطِّ صينية خبز بورق الزبدة.",
"في وعاء صغير، اخلط زيت الزيتون والشبت المفروم وقشر الليمون المبشور وعصير الليمون وملح الكوشر والفلفل.",
"ضع شرائح السلمون والهليون على صينية الخبز واسكب خليط الأعشاب بالملعقة فوق كل شريحة.",
"اخبزه حتى تصل درجة الحرارة الداخلية للسلمون إلى 145° فهرنهايت (65° مئوية)، أي نحو 20 دقيقة، ويصبح الهليون طريًا."])}))
R.append((6636614,{
"es":L("Rábanos asados con romero",
"Descubra el placer único de los rábanos asados, un acompañamiento bajo en carbohidratos que transforma estas vibrantes raíces en un gusto sabroso y apto para personas con diabetes. ¿Lo mejor de todo? ¡Es lo bastante fácil de preparar para cualquier comida entre semana!",
"4","1/2 taza",
["2 tazas de rábanos (sin las puntas y partidos por la mitad)","1 cucharada de aceite de oliva","1/2 cucharadita de romero seco","1/4 cucharadita de sal","1/4 cucharadita de pimienta negra","2 cucharadas de perejil fresco (picado, para decorar)"],
["Precaliente el horno a 400 grados F y cubra una bandeja para hornear con papel pergamino.",
"Mezcle las mitades de rábano con el aceite de oliva, el romero seco, la sal y la pimienta.",
"Ase de 15 a 20 minutos hasta que estén tiernos.",
"Sirva caliente. Decore con perejil fresco picado, si lo desea."]),
"ar":L("فجل مشوي بإكليل الجبل",
"جرّب متعة الفجل المشوي الفريدة، وهو طبق جانبي قليل الكربوهيدرات يحوّل هذه الجذور النابضة بالحياة إلى طبق لذيذ ومناسب لمرضى السكري. والأفضل من ذلك كله؟ أنه سهل التحضير بما يكفي لأي وجبة في أيام الأسبوع!",
"4","½ كوب",
["2 كوب فجل (مقطوع الأطراف ومقسوم إلى نصفين)","1 ملعقة كبيرة زيت زيتون","½ ملعقة صغيرة إكليل الجبل (روزماري) مجفف","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة بقدونس طازج (مفروم، للتزيين)"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200 درجة مئوية) وغطِّ صينية خبز بورق الزبدة.",
"قلّب أنصاف الفجل مع زيت الزيتون وإكليل الجبل المجفف والملح والفلفل.",
"اشوِها لمدة 15–20 دقيقة حتى تصبح طرية.",
"قدّمه دافئًا. زيّنه بالبقدونس الطازج المفروم إن رغبت."])}))
R.append((6637373,{
"es":L("Crujiente de calabaza",
"El crujiente de calabaza es un delicioso postre de otoño que captura los sabores cálidos y especiados de la calabaza en una reconfortante cobertura desmenuzable. Esta versión apta para personas con diabetes es perfecta para un postre navideño más saludable.",
"8","1/4 taza",
["15 onzas de puré de calabaza (enlatado)","2 huevos grandes","1/2 taza de jarabe tipo maple sin azúcar","1/2 taza de leche de almendras sin azúcar","1 cucharadita de extracto de vainilla","2 cucharaditas de canela molida (dividido)","1/2 cucharadita de nuez moscada molida","1/4 cucharadita de jengibre molido","1/4 cucharadita de sal","1 taza de avena en hojuelas tradicional","1/2 taza de harina de almendras","1/4 taza de nueces pecanas (picadas)","2 cucharadas de aceite vegetal"],
["Precaliente el horno a 350 grados F. Forre un molde para hornear de 9 x 9” con papel pergamino.",
"En un tazón, combine el puré de calabaza, los huevos, el jarabe de maple sin calorías, la leche de almendras, el extracto de vainilla, 1 cucharadita de canela molida, la nuez moscada molida, el jengibre molido y la sal.",
"Vierta la mezcla de calabaza en el molde preparado y extiéndala en una capa uniforme.",
"En otro tazón, combine la avena, la harina de almendras, las nueces pecanas picadas, 1 cucharadita de canela y el aceite vegetal. Revuelva hasta que la mezcla quede desmenuzable.",
"Espolvoree la mezcla de avena de manera uniforme sobre la calabaza.",
"Hornee hasta que el relleno de calabaza esté firme y la cobertura de avena esté dorada, aproximadamente 35 minutos.",
"Déjelo enfriar durante 10 minutos y luego sirva caliente."]),
"ar":L("كرِسب القرع (حلوى القرع المقرمشة)",
"كرِسب القرع حلوى خريفية رائعة تجمع نكهات القرع الدافئة والمتبّلة في طبقة علوية مفتتة ومريحة. هذه النسخة المناسبة لمرضى السكري مثالية لحلوى أعياد أكثر صحة.",
"8","¼ كوب",
["15 أونصة هريس القرع (معلب)","2 بيضة كبيرة","½ كوب شراب بنكهة القيقب خالٍ من السكر","½ كوب حليب لوز غير محلى","1 ملعقة صغيرة خلاصة الفانيليا","2 ملعقة صغيرة قرفة مطحونة (تُقسَّم)","½ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة زنجبيل مطحون","¼ ملعقة صغيرة ملح","1 كوب شوفان مجروش تقليدي","½ كوب دقيق اللوز","¼ كوب جوز البقان (مفروم)","2 ملعقة كبيرة زيت نباتي"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175 درجة مئوية). بطّن صينية خبز مقاس 9 × 9 بوصات بورق الزبدة.",
"في وعاء، اخلط هريس القرع والبيض وشراب القيقب الخالي من السعرات وحليب اللوز وخلاصة الفانيليا و1 ملعقة صغيرة من القرفة المطحونة وجوزة الطيب المطحونة والزنجبيل المطحون والملح.",
"اسكب خليط القرع في الصينية المجهزة وافرده في طبقة متساوية.",
"في وعاء آخر، اخلط الشوفان ودقيق اللوز وجوز البقان المفروم و1 ملعقة صغيرة من القرفة والزيت النباتي. قلّب حتى يصبح الخليط مفتتًا.",
"رش خليط الشوفان بالتساوي فوق القرع.",
"اخبزه حتى تتماسك حشوة القرع وتصبح طبقة الشوفان ذهبية اللون، لمدة 35 دقيقة تقريبًا.",
"اتركه يبرد 10 دقائق ثم قدّمه دافئًا."])}))
R.append((6638471,{
"es":L("Bocaditos congelados de yogur con frambuesas sin gluten",
"Una merienda sencilla y sin gluten que combina yogur griego cremoso sin grasa con frambuesas dulces y ácidas, y que se congela en bocaditos del tamaño de un bocado. Son refrescantes, ricos en proteína y perfectos para un postre fresco que se siente indulgente pero conserva su densidad de nutrientes.",
"1","7 bocaditos pequeños",
["3/4 taza de yogur griego natural sin grasa","1 taza de frambuesas"],
["Forre un plato pequeño o una bandeja con papel pergamino.",
"En un tazón, incorpore con suavidad 1 taza de frambuesas en 3/4 de taza de yogur griego sin grasa, dejando algunas frutas enteras para dar textura.",
"Ponga cucharadas pequeñas de la mezcla sobre el papel pergamino para formar los bocaditos.",
"Congele de 1 a 2 horas, o hasta que estén completamente firmes.",
"Disfrútelos directamente del congelador."]),
"ar":L("عناقيد الزبادي بالتوت الأحمر المجمدة الخالية من الغلوتين",
"وجبة خفيفة بسيطة وخالية من الغلوتين تجمع بين الزبادي اليوناني الكريمي الخالي من الدسم والتوت الأحمر الحلو الحامض، وتتجمد على شكل عناقيد بحجم لقمة. إنها منعشة وغنية بالبروتين ومثالية لحلوى باردة تبدو مدللة لكنها تحافظ على كثافتها الغذائية.",
"1","7 عناقيد صغيرة",
["¾ كوب زبادي يوناني سادة خالٍ من الدسم","1 كوب توت أحمر (راسبيري)"],
["بطّن طبقًا صغيرًا أو صينية بورق الزبدة.",
"في وعاء، أضف برفق 1 كوب من التوت الأحمر إلى ¾ كوب من الزبادي اليوناني الخالي من الدسم، مع إبقاء بعض الحبات كاملة لإضفاء قوام.",
"ضع كميات صغيرة من الخليط بالملعقة على ورق الزبدة لتشكيل العناقيد.",
"ضعها في المجمد لمدة 1–2 ساعة، أو حتى تتماسك تمامًا.",
"استمتع بها مباشرة من المجمد."])}))
R.append((6638576,{
"es":L("Claras de huevo, 1/2 taza","Información nutricional de las claras de huevo cocidas.","1","1/2 taza de claras de huevo líquidas",
["1/2 taza de claras de huevo líquidas","1 rocío de aceite en aerosol"],
["Cubra ligeramente un sartén antiadherente pequeño con aceite en aerosol y póngalo a fuego medio.",
"Vierta 1/2 taza de claras de huevo líquidas en el sartén caliente.",
"Deje que las claras se cocinen sin moverlas de 1 a 2 minutos, hasta que empiecen a cuajar por los bordes.",
"Revuélvalas con suavidad, dóblelas o déjelas enteras, según prefiera claras revueltas suaves o una forma estilo tortilla.",
"Continúe la cocción de 1 a 2 minutos más, hasta que las claras estén completamente cuajadas y ya no estén líquidas.",
"Retire del fuego y sirva de inmediato."]),
"ar":L("بياض البيض، ½ كوب","المعلومات الغذائية لطهي بياض البيض.","1","½ كوب بياض بيض سائل",
["½ كوب بياض بيض سائل","1 بخّة بخاخ طهي"],
["ادهن مقلاة صغيرة غير لاصقة برفق ببخاخ الطهي وضعها على نار متوسطة.",
"اسكب ½ كوب من بياض البيض السائل في المقلاة الدافئة.",
"اترك بياض البيض يُطهى دون تحريك لمدة 1–2 دقيقة حتى يبدأ بالتماسك عند الحواف.",
"قلّبه برفق أو اطوِه أو اتركه كاملًا — بحسب ما إذا كنت تريد بياضًا مخفوقًا طريًا أو بشكل أومليت.",
"واصل الطهي لمدة 1–2 دقيقة أخرى حتى يتماسك بياض البيض تمامًا ولا يعود سائلًا.",
"ارفعه عن النار وقدّمه فورًا."])}))
